/* prog31_gcd_lcm – reproduced from the original binary
 *
 * Behaviour:
 *   prog31_gcd_lcm a b
 *
 *   - If the number of arguments is not exactly 2 → prints "USAGE"
 *   - If either argument is not a valid decimal integer → prints "BAD_INPUT"
 *   - If |a| > 1 000 000 or |b| > 1 000 000 → prints "OUT_OF_RANGE"
 *   - If a == LLONG_MIN or b == LLONG_MIN → prints "OVERFLOW"
 *   - If a == 0 and b == 0 → prints "gcd=0 lcm=0"
 *   - Otherwise prints "gcd=<gcd> lcm=<lcm>"
 *     (gcd = greatest common divisor, lcm = least common multiple)
 *   - If the lcm calculation overflows a signed 64‑bit integer → prints
 *     "OVERFLOW"
 *
 * All messages end with a newline, exactly as the original program does.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <stdbool.h>
#include <stdint.h>
#include <errno.h>

static bool parse_long(const char *s, long *out)
{
    char *endptr;
    errno = 0;                     /* reset errno for safety */
    long v = strtol(s, &endptr, 10);
    if (endptr == s || *endptr != '\0')
        return false;             /* conversion failed */
    *out = v;
    return true;
}

/* Euclidean algorithm for non‑negative numbers */
static long gcd_long(long a, long b)
{
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

/* Compute lcm = (a / g) * b using 128‑bit arithmetic.
 * Returns true on success, false if the result does not fit in a signed
 * 64‑bit integer. */
static bool lcm_long(long a, long b, long g, long *out)
{
    __int128 tmp = (__int128)(a / g) * (__int128)b;
    if (tmp > LLONG_MAX || tmp < LLONG_MIN)
        return false;
    *out = (long)tmp;
    return true;
}

int main(int argc, char **argv)
{
    /* 1. argument count */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    long a, b;
    /* 2. parsing */
    if (!parse_long(argv[1], &a) || !parse_long(argv[2], &b)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* 3. range check (absolute value) */
    if (a > 1000000L || a < -1000000L || b > 1000000L || b < -1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 5. overflow when taking absolute value of LLONG_MIN */
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    /* 4. special case both zero */
    if (a == 0 && b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    /* 6. work with absolute values */
    long abs_a = a < 0 ? -a : a;
    long abs_b = b < 0 ? -b : b;

    /* 6. gcd */
    long g = gcd_long(abs_a, abs_b);

    /* 7. lcm with overflow detection */
    long l;
    if (!lcm_long(abs_a, abs_b, g, &l)) {
        puts("OVERFLOW");
        return 0;
    }

    /* 8. final result */
    printf("gcd=%ld lcm=%ld\n", g, l);
    return 0;
}
